head.script:
scwin.multiDown = function(grid1id, grid2id) {
    var options = {
        common: {
            fileName: "sample.xls",
            showProcess: false
        },
        //excelInfo에 각 그리드의 정보를 입력한다.
        excelInfo: [{
                gridId: grid1id,
                sheetName: "첫번째 sheet",
                removeColumns: ""
            },
            {
                gridId: grid2id,
                sheetName: "두번째 sheet",
                removeColumns: ""
            }
        ]
    };
    WebSquare.util.multipleExcelDownload(options);
};
scwin.trigger1_onclick = function(e) {
    scwin.multiDown("gridView1", "gridView2");
};
scwin.trigger2_onclick = function(e) {
    //debugger;
    //alert(ret1);
    isShowAlert = true;
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. Script 탭 또는 Source 탭에서 var ret1 부분을 확인한다. 
    //1. Check the var ret1 field in the Script tab or Source tab.
    // verify step 1. var ret1 = $w.data.getAllDataCollection(); 
    //Test step 2. var ret2 부분을 확인한다. 
    //2. Check the var ret2 part.
    //2. var ret2 = $w.data.getAllDataCollection('object'); 
    //Test step 3. scwin.trigger2_onclick 부분을 확인한다. 
    //3. Check the scwin.trigger2_onclick section.
    //Verify step 3. alert(ret1); 
    //Test step 4. 브라우저에서 ID 반환 버튼을 클릭한다. 
    //4. Click the Return ID button in your browser.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 4. 데이터리스트 ID에 대한 팝업이 생성된다. 
    //4. A pop-up is created for the data list ID.
    //Test step 5. 개발자도구 (F12) 를 실행한다. 
    //5. Run Developer Tools (F12).
    //Verify step 5. 개발자도구가 실행된다. 
    //5. The developer tool is launched.
    //Test step 6. 각 개발자도구에 맞게 watch 에 ret2 를 등록한다. (코멘트 확인)
    //6. Register ret2 on watch for each developer tool. (Comment confirmation)
    //Verify step 6. object 정보가 나온다.
    //6. The object information is displayed.
    WebSquare.wUnit.addCommand("assert", "ret2.length > 0", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //sampleData1
    window.data1 = [{
            "col1": "a",
            "col2": "1000"
        },
        {
            "col1": "b",
            "col2": "2000"
        },
        {
            "col1": "c",
            "col2": "3000"
        },
        {
            "col1": "d",
            "col2": "4000"
        }
    ];
    //sampleData2
    window.data2 = [{
            "col1": "a",
            "col2": "1000"
        },
        {
            "col1": "c",
            "col2": "3000"
        }
    ];
    dataList1.setJSON(data1);
    dataList2.setJSON(data2);
    //MultiExcelDownload Function
    window.isShowAlert = false;
    window.ret1 = $w.data.getAllDataCollection();
    // ret == ["dataList1","dataList2"]   
    // 기본적으로는 각 객체의 id를 배열에 담아 반환합니다. 
    window.ret2 = $w.data.getAllDataCollection("object");
    // ret == [dataList1,dataList2]
    // 함수 호출 시 "object"라는 인자를 넣어서 호출하면 id가 아니라 객체를 반환합니다. 
    //Function unitTest
    //Created By: Sang.do
    //Created By: 06-Feb-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
